### Module 2: File Upload Gateway

This gateway processes uploads directly as incoming streams to prevent Large Object Heap (LOH) exhaustion. It integrates an active stream-based antivirus scan and prevents path-traversal attacks.

```csharp
using System;
using System.Buffers;
using System.IO;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using EnterpriseDMS.Core;

namespace EnterpriseDMS.UploadGateway
{
    public record ScanResult(bool IsClean, string ThreatName, TimeSpan ScanDuration);

    public interface IAntiVirusScanner
    {
        Task<ScanResult> ScanStreamAsync(Stream stream, CancellationToken cancellationToken = default);
    }

    /// <summary>
    /// Implements real-time, zero-allocation signature pattern checking (EICAR and test malware strings) over streams.
    /// </summary>
    public class StreamingAntiVirusScanner : IAntiVirusScanner
    {
        private static readonly byte[] EicarSignature = Encoding.ASCII.GetBytes(@"X5O!P%@AP[4\PZX54(P^)7CC)7}$EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*");
        private static readonly byte[] CustomMalwareSignature = Encoding.ASCII.GetBytes("MALWARE_EXPLOIT_SIGNATURE_99");

        public async Task<ScanResult> ScanStreamAsync(Stream stream, CancellationToken cancellationToken = default)
        {
            var startTime = DateTime.UtcNow;

            // Sliding window buffer scanning
            const int bufferSize = 4096;
            byte[] buffer = ArrayPool<byte>.Shared.Rent(bufferSize);
            int overlap = Math.Max(EicarSignature.Length, CustomMalwareSignature.Length) - 1;
            int bytesRead;
            int offset = 0;

            try
            {
                if (stream.CanSeek)
                {
                    stream.Position = 0;
                }

                while ((bytesRead = await stream.ReadAsync(buffer.AsMemory(offset, bufferSize - offset), cancellationToken)) > 0)
                {
                    int totalInBuf = bytesRead + offset;
                    var window = buffer.AsSpan(0, totalInBuf);

                    if (ContainsSequence(window, EicarSignature))
                    {
                        return new ScanResult(false, "EICAR-Test-Signature", DateTime.UtcNow - startTime);
                    }
                    if (ContainsSequence(window, CustomMalwareSignature))
                    {
                        return new ScanResult(false, "Trojan.Win32.GenericEDMS", DateTime.UtcNow - startTime);
                    }

                    // Handle boundary overlap
                    if (totalInBuf > overlap)
                    {
                        Array.Copy(buffer, totalInBuf - overlap, buffer, 0, overlap);
                        offset = overlap;
                    }
                    else
                    {
                        offset = totalInBuf;
                    }
                }
            }
            finally
            {
                ArrayPool<byte>.Shared.Return(buffer);
            }

            return new ScanResult(true, string.Empty, DateTime.UtcNow - startTime);
        }

        private static bool ContainsSequence(ReadOnlySpan<byte> source, ReadOnlySpan<byte> target)
        {
            return source.IndexOf(target) >= 0;
        }
    }

    /// <summary>
    /// Processes multi-part streams to prevent memory exhaustion and secure physical storage.
    /// </summary>
    public class SafePhysicalStorageWriter
    {
        private readonly string _storageRoot;

        public SafePhysicalStorageWriter(string storageRoot)
        {
            _storageRoot = Path.GetFullPath(storageRoot);
            if (!Directory.Exists(_storageRoot))
            {
                Directory.CreateDirectory(_storageRoot);
            }
        }

        public async Task<string> SaveStreamAsync(Stream sourceStream, string fileName, CancellationToken cancellationToken = default)
        {
            // Path Traversal Mitigation: Ensure canonical paths lie strictly inside storage root
            string safeName = Path.GetFileName(fileName);
            string destinationPath = Path.GetFullPath(Path.Combine(_storageRoot, safeName));

            if (!destinationPath.StartsWith(_storageRoot, StringComparison.OrdinalIgnoreCase))
            {
                throw new SecurityException("Directory Traversal Attempt Detected!");
            }

            using var destinationStream = new FileStream(
                destinationPath, 
                FileMode.Create, 
                FileAccess.Write, 
                FileShare.None, 
                bufferSize: 8192, 
                useAsync: true);

            if (sourceStream.CanSeek)
            {
                sourceStream.Position = 0;
            }

            await sourceStream.CopyToAsync(destinationStream, cancellationToken);
            return destinationPath;
        }
    }

    /// <summary>
    /// Fast, low-overhead multi-part MIME stream parser
    /// </summary>
    public class MultipartStreamParser
    {
        public static async Task<MemoryStream> ExtractPartContentAsync(Stream multipartStream, string boundary, CancellationToken cancellationToken = default)
        {
            var output = new MemoryStream();
            byte[] boundaryBytes = Encoding.ASCII.GetBytes($"--{boundary}");
            byte[] buffer = ArrayPool<byte>.Shared.Rent(8192);

            try
            {
                int bytesRead;
                bool bodyStarted = false;

                // Read chunks, parse MIME structural lines, and separate boundary overhead from payloads
                while ((bytesRead = await multipartStream.ReadAsync(buffer.AsMemory(), cancellationToken)) > 0)
                {
                    var span = buffer.AsSpan(0, bytesRead);

                    if (!bodyStarted)
                    {
                        // Search for the end of MIME headers (CRLF CRLF sequence)
                        int headerEndIdx = span.IndexOf(Encoding.ASCII.GetBytes("\r\n\r\n"));
                        if (headerEndIdx != -1)
                        {
                            bodyStarted = true;
                            int contentStart = headerEndIdx + 4;
                            output.Write(buffer, contentStart, bytesRead - contentStart);
                        }
                    }
                    else
                    {
                        int boundaryIdx = span.IndexOf(boundaryBytes);
                        if (boundaryIdx != -1)
                        {
                            // Strip terminating carriage returns
                            int finalWriteLength = boundaryIdx;
                            if (boundaryIdx >= 2 && buffer[boundaryIdx - 1] == '\n' && buffer[boundaryIdx - 2] == '\r')
                            {
                                finalWriteLength -= 2;
                            }
                            output.Write(buffer, 0, finalWriteLength);
                            break;
                        }
                        output.Write(buffer, 0, bytesRead);
                    }
                }
            }
            finally
            {
                ArrayPool<byte>.Shared.Return(buffer);
            }

            output.Position = 0;
            return output;
        }
    }
}
