### Module 3: Full-Text Indexing Engine

This engine features thread-safe, lock-free concurrency mechanics, high-performance regex tokenization with stop-word exclusions, and TF-IDF rank scoring.

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using EnterpriseDMS.Core;

namespace EnterpriseDMS.IndexingEngine
{
    public record SearchResult(Guid DocumentId, double Score);

    public interface IInvertedIndexEngine
    {
        void IndexDocument(Guid documentId, string content);
        IEnumerable<SearchResult> Search(string query, int maxResults = 10);
        void RemoveDocument(Guid documentId);
    }

    public class ConcurrentInvertedIndexEngine : IInvertedIndexEngine
    {
        private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
        {
            "a", "about", "above", "after", "again", "against", "all", "am", "an", "and", "any", "are", "aren't", 
            "as", "at", "be", "because", "been", "before", "being", "below", "between", "both", "but", "by", "can't", 
            "cannot", "could", "couldn't", "did", "didn't", "do", "does", "doesn't", "doing", "don't", "down", "during", 
            "each", "few", "for", "from", "further", "had", "hadn't", "has", "hasn't", "have", "haven't", "having", "he", 
            "her", "here", "hers", "herself", "him", "himself", "his", "how", "i", "if", "in", "into", "is", "isn't", 
            "it", "it's", "its", "itself", "me", "more", "most", "mustn't", "my", "myself", "no", "nor", "not", "of", "off", 
            "on", "once", "only", "or", "other", "ought", "our", "ours", "ourselves", "out", "over", "own", "same", "she", 
            "should", "shouldn't", "so", "some", "such", "than", "that", "the", "their", "theirs", "them", "themselves", 
            "then", "there", "these", "they", "this", "those", "through", "to", "too", "under", "until", "up", "very", 
            "was", "wasn't", "we", "were", "weren't", "what", "when", "where", "which", "while", "who", "whom", "why", 
            "with", "won't", "would", "wouldn't", "you", "your", "yours", "yourself", "yourselves"
        };

        private static readonly Regex TokenizationRegex = new(@"[^\w\d]+", RegexOptions.Compiled);

        // Core Inverted Index Structure: Term -> (DocumentId -> Occurrence Count)
        private readonly ConcurrentDictionary<string, ConcurrentDictionary<Guid, int>> _index = new(StringComparer.OrdinalIgnoreCase);
        private readonly ConcurrentDictionary<Guid, int> _documentTotalTerms = new();
        private readonly ConcurrentDictionary<Guid, string> _rawDocuments = new();

        public void IndexDocument(Guid documentId, string content)
        {
            if (string.IsNullOrWhiteSpace(content)) return;

            _rawDocuments[documentId] = content;
            var tokens = Tokenize(content);
            if (tokens.Length == 0) return;

            _documentTotalTerms[documentId] = tokens.Length;

            // Compute local frequencies inside document
            var localFrequencies = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (var token in tokens)
            {
                localFrequencies[token] = localFrequencies.GetValueOrDefault(token) + 1;
            }

            // Secure thread-safe merge into inverted index
            foreach (var (term, count) in localFrequencies)
            {
                var docMap = _index.GetOrAdd(term, _ => new ConcurrentDictionary<Guid, int>());
                docMap[documentId] = count;
            }
        }

        public IEnumerable<SearchResult> Search(string query, int maxResults = 10)
        {
            var queryTerms = Tokenize(query).Distinct().ToArray();
            if (queryTerms.Length == 0 || _documentTotalTerms.IsEmpty)
            {
                return Enumerable.Empty<SearchResult>();
            }

            double totalDocs = _documentTotalTerms.Count;
            var docScores = new ConcurrentDictionary<Guid, double>();

            // Thread-safe TF-IDF ranking
            foreach (var term in queryTerms)
            {
                if (_index.TryGetValue(term, out var postings))
                {
                    double documentFrequency = postings.Count;
                    if (documentFrequency == 0) continue;

                    // Compute inverse document frequency (IDF) with smoothed division
                    double idf = Math.Log(1.0 + (totalDocs / documentFrequency));

                    foreach (var (docId, count) in postings)
                    {
                        double termCount = count;
                        double totalDocTerms = _documentTotalTerms.GetValueOrDefault(docId, 1);
                        double tf = termCount / totalDocTerms;

                        docScores.AddOrUpdate(docId, tf * idf, (_, oldScore) => oldScore + (tf * idf));
                    }
                }
            }

            return docScores
                .Select(pair => new SearchResult(pair.Key, pair.Value))
                .OrderByDescending(res => res.Score)
                .Take(maxResults);
        }

        public void RemoveDocument(Guid documentId)
        {
            _documentTotalTerms.TryRemove(documentId, out _);
            _rawDocuments.TryRemove(documentId, out _);

            foreach (var termMapping in _index.Values)
            {
                termMapping.TryRemove(documentId, out _);
            }
        }

        private static string[] Tokenize(string rawText)
        {
            return TokenizationRegex.Split(rawText.ToLowerInvariant())
                .Where(t => t.Length > 1 && !StopWords.Contains(t))
                .ToArray();
        }
    }
}
