### Module 4: Role-Based Access Control (RBAC) & ABAC Subsystem

This module enforces user privileges using dynamic Hierarchical Role graphs combined with Attribute-Based Access Control (ABAC). It evaluates properties like spatial/IP criteria, working hour restrictions, and data classification clearance.

```csharp
using System;
using System.Collections.Generic;
using EnterpriseDMS.Core;

namespace EnterpriseDMS.Security
{
    public class RoleHierarchy
    {
        private readonly Dictionary<string, HashSet<string>> _roleInheritanceGraph = new(StringComparer.OrdinalIgnoreCase);

        public void RegisterInheritance(string parentRole, string childRole)
        {
            if (!_roleInheritanceGraph.TryGetValue(parentRole, out var children))
            {
                children = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                _roleInheritanceGraph[parentRole] = children;
            }
            children.Add(childRole);
        }

        public bool Implies(string activeRole, string targetRole)
        {
            if (activeRole.Equals(targetRole, StringComparison.OrdinalIgnoreCase)) return true;

            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var queue = new Queue<string>();
            queue.Enqueue(activeRole);
            visited.Add(activeRole);

            while (queue.Count > 0)
            {
                var current = queue.Dequeue();
                if (_roleInheritanceGraph.TryGetValue(current, out var children))
                {
                    foreach (var child in children)
                    {
                        if (child.Equals(targetRole, StringComparison.OrdinalIgnoreCase)) return true;
                        if (visited.Add(child))
                        {
                            queue.Enqueue(child);
                        }
                    }
                }
            }
            return false;
        }
    }

    public interface ISecurityRule
    {
        bool Evaluate(SecurityContext subject, DocumentMetadata resource, DocumentPermission permission);
    }

    public class HierarchyRbacRule : ISecurityRule
    {
        private readonly RoleHierarchy _hierarchy;
        private readonly Dictionary<string, HashSet<DocumentPermission>> _rolePermissions;

        public HierarchyRbacRule(RoleHierarchy hierarchy, Dictionary<string, HashSet<DocumentPermission>> rolePermissions)
        {
            _hierarchy = hierarchy;
            _rolePermissions = rolePermissions;
        }

        public bool Evaluate(SecurityContext subject, DocumentMetadata resource, DocumentPermission permission)
        {
            foreach (var role in _rolePermissions.Keys)
            {
                if (_hierarchy.Implies(subject.ActiveRole, role))
                {
                    if (_rolePermissions[role].Contains(permission))
                    {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    public class ClearanceLevelAbacRule : ISecurityRule
    {
        public bool Evaluate(SecurityContext subject, DocumentMetadata resource, DocumentPermission permission)
        {
            // Clearance must equal or exceed file classification
            return (int)subject.Clearance >= (int)resource.Classification;
        }
    }

    public class DepartmentSegregationAbacRule : ISecurityRule
    {
        public bool Evaluate(SecurityContext subject, DocumentMetadata resource, DocumentPermission permission)
        {
            // Exception: System Administrators bypass department segregation locks
            if (subject.ActiveRole.Equals("SystemAdmin", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Only owners or regional department peers can access non-public elements
            return resource.Classification == ClassificationLevel.Unclassified || 
                   subject.Department.Equals(resource.Department, StringComparison.OrdinalIgnoreCase);
        }
    }

    public class ContextualEnvironmentAbacRule : ISecurityRule
    {
        public bool Evaluate(SecurityContext subject, DocumentMetadata resource, DocumentPermission permission)
        {
            // Temporal constraints: Restrict file deletion/writes to business hours (06:00 to 22:00 UTC)
            if (permission is DocumentPermission.Delete or DocumentPermission.Write)
            {
                int hour = subject.RequestTime.Hour;
                if (hour < 6 || hour > 22)
                {
                    return false;
                }
            }

            // Spatial/Network constraints: Require internal private subnets for Confidential/Secret/TopSecret resources
            if (resource.Classification > ClassificationLevel.Unclassified)
            {
                bool isLocalHost = subject.IpAddress == "127.0.0.1" || subject.IpAddress == "::1";
                bool isCorporateSubnet = subject.IpAddress.StartsWith("10.0.") || subject.IpAddress.StartsWith("192.168.");

                if (!isLocalHost && !isCorporateSubnet)
                {
                    return false;
                }
            }

            return true;
        }
    }

    public class SecurityEngine
    {
        private readonly List<ISecurityRule> _rules = new();

        public void RegisterRule(ISecurityRule rule) => _rules.Add(rule);

        public void EnforcePolicy(SecurityContext subject, DocumentMetadata resource, DocumentPermission action)
        {
            foreach (var rule in _rules)
            {
                if (!rule.Evaluate(subject, resource, action))
                {
                    throw new SecurityException($"Access Denied: Dynamic policy evaluation failed on rule: {rule.GetType().Name}. Subject context lacks permissions for requested resource {resource.Id}.");
                }
            }
        }
    }
}
