### Execution Harness & Integration Tests

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using EnterpriseDMS.Core;
using EnterpriseDMS.IndexingEngine;
using EnterpriseDMS.Security;
using EnterpriseDMS.UploadGateway;

namespace EnterpriseDMS
{
    public class Program
    {
        private static string StorageDirectory = Path.Combine(Path.GetTempPath(), "EDMS_Storage_Test");

        public static async Task Main()
        {
            try
            {
                Console.ForegroundColor = ConsoleColor.Cyan;
                Console.WriteLine("======================================================================");
                Console.WriteLine("      BUILDING modular ENTERPRISE DOCUMENT MANAGEMENT SYSTEM");
                Console.WriteLine("======================================================================");
                Console.ResetColor();

                // 1. Initialize Subsystems & Rules Engines
                var roleHierarchy = new RoleHierarchy();
                roleHierarchy.RegisterInheritance("SystemAdmin", "ComplianceOfficer");
                roleHierarchy.RegisterInheritance("ComplianceOfficer", "Manager");
                roleHierarchy.RegisterInheritance("Manager", "Staff");
                roleHierarchy.RegisterInheritance("Staff", "Guest");

                var rolePermissions = new Dictionary<string, HashSet<DocumentPermission>>
                {
                    { "SystemAdmin", new HashSet<DocumentPermission> { DocumentPermission.Read, DocumentPermission.Write, DocumentPermission.Delete, DocumentPermission.Audit } },
                    { "Manager", new HashSet<DocumentPermission> { DocumentPermission.Read, DocumentPermission.Write } },
                    { "Staff", new HashSet<DocumentPermission> { DocumentPermission.Read, DocumentPermission.Write } },
                    { "Guest", new HashSet<DocumentPermission> { DocumentPermission.Read } }
                };

                var securityEngine = new SecurityEngine();
                securityEngine.RegisterRule(new HierarchyRbacRule(roleHierarchy, rolePermissions));
                securityEngine.RegisterRule(new ClearanceLevelAbacRule());
                securityEngine.RegisterRule(new DepartmentSegregationAbacRule());
                securityEngine.RegisterRule(new ContextualEnvironmentAbacRule());

                var scanner = new StreamingAntiVirusScanner();
                var indexEngine = new ConcurrentInvertedIndexEngine();
                var documentService = new EnterpriseDocumentService(StorageDirectory, scanner, indexEngine, securityEngine);

                // Define user profiles
                var adminUser = new SecurityContext("USR-001", "SystemAdmin", ClassificationLevel.TopSecret, "IT", "127.0.0.1", DateTime.UtcNow);
                var hrManager = new SecurityContext("USR-002", "Manager", ClassificationLevel.Secret, "HR", "192.168.1.45", DateTime.UtcNow);
                var guestUser = new SecurityContext("USR-003", "Guest", ClassificationLevel.Unclassified, "Public", "8.8.8.8", DateTime.UtcNow);
                var financialAnalyst = new SecurityContext("USR-004", "Staff", ClassificationLevel.Confidential, "Finance", "10.0.4.12", DateTime.UtcNow);

                // Run validation scenarios
                await RunSuccessScenario(documentService, hrManager, financialAnalyst, adminUser);
                await RunMalwareBlockingScenario(documentService, hrManager);
                await RunSecurityAccessViolationsScenario(documentService, hrManager, guestUser);
            }
            finally
            {
                // Clean up physical file generation directories
                if (Directory.Exists(StorageDirectory))
                {
                    Directory.Delete(StorageDirectory, true);
                }
            }
        }

        private static async Task RunSuccessScenario(
            EnterpriseDocumentService service, 
            SecurityContext creator, 
            SecurityContext authorizedReader,
            SecurityContext adminReader)
        {
            Console.WriteLine("\n--- [SCENARIO 1: Clean Multipart File Upload & Inverted Indexing] ---");

            const string boundary = "---------------------------9051914041544843365972754266";
            var rawRequestPayload = 
                $"--{boundary}\r\n" +
                "Content-Disposition: form-data; name=\"file\"; filename=\"quarterly_report.txt\"\r\n" +
                "Content-Type: text/plain\r\n\r\n" +
                "This document describes the financial reports and performance. Quarterly yields exceeded expectations.\r\n" +
                "Revenue projections are confidential.\r\n" +
                $"--{boundary}--";

            using var uploadStream = new MemoryStream(Encoding.ASCII.GetBytes(rawRequestPayload));

            var docMeta = await service.ProcessIncomingUploadAsync(
                creator,
                uploadStream,
                boundary,
                "quarterly_report.txt",
                "Finance",
                ClassificationLevel.Confidential
            );

            Console.ForegroundColor = ConsoleColor.Green;
            Console.WriteLine($"[✓] Document successfully registered. Storage path: {docMeta.StoragePath}");
            Console.ResetColor();

            // Run search against the inverted index using search terms
            Console.WriteLine("\nSearching for keyword: \"confidential\"...");
            var results = service.SearchDocuments(authorizedReader, "confidential");

            foreach (var result in results)
            {
                var meta = service.RetrieveDocumentMetadata(authorizedReader, result.DocumentId);
                Console.WriteLine($"[Result Hit] Doc: {meta.Title} | Relevancy Score: {result.Score:F4}");
                Console.WriteLine($"[Read Authorized] Contents: {service.ReadDocumentContents(authorizedReader, result.DocumentId)}");
